import React,{useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import './styles.css';

const starter={
 'lib/main.dart':"import 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n  @override\n  Widget build(BuildContext context) => const MaterialApp(home: Scaffold(body: Center(child: Text('Generated by AI Flutter App Builder'))));\n}",
 'pubspec.yaml':"name: my_ai_app\ndescription: Generated by AI Flutter App Builder\nenvironment:\n  sdk: '>=3.0.0 <4.0.0'\ndependencies:\n  flutter:\n    sdk: flutter\nflutter:\n  uses-material-design: true",
 'README.md':"# My AI App\n\nGenerated by AI Flutter App Builder."
};

function App(){
 const [projects,setProjects]=useState(()=>JSON.parse(localStorage.getItem('projects')||'[]'));
 const [active,setActive]=useState(()=>localStorage.getItem('active')||'');
 const [files,setFiles]=useState(()=>JSON.parse(localStorage.getItem('files')||'null')||starter);
 const [builds,setBuilds]=useState(()=>JSON.parse(localStorage.getItem('builds')||'[]'));
 const [tab,setTab]=useState('dashboard'),[prompt,setPrompt]=useState(''),[file,setFile]=useState('lib/main.dart');
 const [chat,setChat]=useState([{r:'AI',t:'Describe the Flutter app you want to build. Groq will generate real project files through the secure backend.'}]);
 const [aiBusy,setAiBusy]=useState(false); const apiUrl=import.meta.env.VITE_AI_API_URL||'';
 useEffect(()=>localStorage.setItem('projects',JSON.stringify(projects)),[projects]);
 useEffect(()=>localStorage.setItem('active',active),[active]); useEffect(()=>localStorage.setItem('files',JSON.stringify(files)),[files]); useEffect(()=>localStorage.setItem('builds',JSON.stringify(builds)),[builds]);
 const project=projects.find(x=>x.id===active);
 async function createProject(){const d=prompt.trim()||'Build a modern Flutter application.';const p={id:crypto.randomUUID(),name:d.slice(0,36),description:d,status:'generating',updatedAt:new Date().toISOString()};setProjects(x=>[p,...x]);setActive(p.id);setTab('builder');setAiBusy(true);setChat([{r:'You',t:d},{r:'AI',t:'Generating your Flutter project with Groq…'}]);try{if(!apiUrl)throw new Error('AI backend is not configured. Set VITE_AI_API_URL.');const r=await fetch(apiUrl+'/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:d,files:Object.entries(starter).map(([path,content])=>({path,content}))})});const data=await r.json();if(!r.ok)throw new Error(data.error||'AI generation failed');const next={...starter};(data.files||[]).forEach(x=>{next[x.path]=x.content});setFiles(next);setProjects(x=>x.map(v=>v.id===p.id?{...v,status:'ready',updatedAt:new Date().toISOString()}:v));setChat([{r:'AI',t:data.message||'Project generated successfully with Groq.'}]);}catch(e){setProjects(x=>x.map(v=>v.id===p.id?{...v,status:'draft'}:v));setChat(c=>[...c,{r:'AI',t:e.message}]);}finally{setAiBusy(false);}}
 function build(format){if(!project)return;setBuilds([{id:crypto.randomUUID(),projectId:project.id,format,status:'queued',message:'External Flutter build runner is not configured.',createdAt:new Date().toISOString()},...builds]);setTab('builds');}
 async function send(){const q=prompt.trim();if(!q||aiBusy)return;setAiBusy(true);setChat(c=>[...c,{r:'You',t:q},{r:'AI',t:'Thinking with Groq…'}]);setPrompt('');try{if(!apiUrl)throw new Error('AI backend is not configured.');const r=await fetch(apiUrl+'/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:q,files:Object.entries(files).map(([path,content])=>({path,content}))})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Groq request failed');const next={...files};(data.files||[]).forEach(x=>next[x.path]=x.content);setFiles(next);setChat(c=>[...c.slice(0,-1),{r:'AI',t:data.message||'Changes generated and applied.'}]);}catch(e){setChat(c=>[...c.slice(0,-1),{r:'AI',t:e.message}]);}finally{setAiBusy(false);}}
 return <div className="app"><aside><div className="brand"><strong>✦ AI Flutter</strong><small>App Builder</small></div>{[['dashboard','⌂ Dashboard'],['projects','▣ Projects'],['builder','⌘ Builder'],['builds','▶ Build Jobs']].map(x=><button className={tab===x[0]?'nav active':'nav'} onClick={()=>setTab(x[0])} key={x[0]}>{x[1]}</button>)}<div className="runner">● Build Runner<br/><small>Not configured</small></div></aside>
 <main><header><div><small>AI DEVELOPMENT WORKSPACE</small><h1>{tab==='builder'&&project?project.name:'AI Flutter App Builder'}</h1></div><button className="primary" onClick={()=>setTab('dashboard')}>＋ New Project</button></header>
 {tab==='dashboard'&&<section><div className="hero"><span>FLUTTER • AI • REAL SOURCE FILES</span><h2>Turn an idea into a Flutter project.</h2><p>Describe your app, inspect source files, edit code, and hand builds to an external Flutter runner.</p></div><div className="prompt"><textarea id="prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Build a WhatsApp-style messenger with login, private chats and image sharing..."/><div><small>Generation and builds are shown honestly; unavailable services are never faked.</small><button className="primary" disabled={aiBusy} onClick={createProject}>{aiBusy?'Generating…':'Generate Project ✨'}</button></div></div><div className="examples">{['WhatsApp-style messenger','AI chatbot','Food delivery app','E-commerce app'].map(x=><button onClick={()=>setPrompt('Build a '+x+' with a polished mobile UI.')} key={x}>{x} →</button>)}</div><h3>Recent projects</h3>{projects.slice(0,4).map(p=><Card p={p} open={()=>{setActive(p.id);setTab('builder')}} key={p.id}/>)}{!projects.length&&<div className="empty">No projects yet.</div>}</section>}
 {tab==='projects'&&<section><div className="title"><div><h2>Your projects</h2><p>Project records currently persist locally; connect a backend for multi-user persistence.</p></div></div>{projects.map(p=><Card p={p} open={()=>{setActive(p.id);setTab('builder')}} key={p.id}/>)}{!projects.length&&<div className="empty">No projects.</div>}</section>}
 {tab==='builder'&&<section className="builder">{!project?<div className="empty">Select a project first.</div>:<><div className="bar"><span className="badge">{project.status}</span><button onClick={()=>build('apk')}>Build APK</button><button onClick={()=>build('aab')}>Build AAB</button></div><div className="ide"><div className="files"><b>FILES</b>{Object.keys(files).map(f=><button className={file===f?'selected':''} onClick={()=>setFile(f)} key={f}>{f}</button>)}</div><div className="editor"><div>{file}<span>● Saved</span></div><textarea value={files[file]||''} onChange={e=>setFiles({...files,[file]:e.target.value})}/></div><div className="assistant"><b>AI ASSISTANT</b><div className="chat">{chat.map((m,i)=><div className="msg" key={i}><strong>{m.r}</strong><p>{m.t}</p></div>)}</div><div className="chatbox"><input value={prompt} onChange={e=>setPrompt(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Ask AI to change the app..."/><button onClick={send}>↑</button></div></div></div></>}</section>}
 {tab==='builds'&&<section><h2>Build jobs</h2><p className="muted">Only an external Flutter runner can produce real APK/AAB artifacts.</p>{builds.map(b=><div className="build"><strong>{b.format.toUpperCase()}</strong><span className="badge yellow">{b.status}</span><p>{b.message}</p><small>{new Date(b.createdAt).toLocaleString()}</small></div>)}{!builds.length&&<div className="empty">No build jobs yet.</div>}</section>}
 </main></div>
}
function Card({p,open}){return <div className="card"><div className="icon">⌁</div><div><h3>{p.name}</h3><p>{p.description}</p><small className="badge">{p.status}</small></div><button onClick={open}>Open →</button></div>}
createRoot(document.getElementById('root')).render(<App/>);